// Differential tests of the OpenSCAD interpreter: each snippet (our own) was run through OpenSCAD 2021.01
// (`openscad -o out.echo main.scad`, with -D for the override cases) and its console output recorded here. The output
// is normalized the same way on both sides: DEPRECATED lines count as warnings, TRACE lines are dropped, file names
// are reduced to the base name, syntax errors read "Parser error in file …, line N" (our messages say more), and the
// main code is "the main code" where OpenSCAD names main.scad, and recursion deeper than 3Dica can go reads as
// OpenSCAD's "Recursion detected calling …" (ours says how deep it got, as it may be a recursion that ends).
// Known differences, tested in scad-lang-unit.test.ts instead: syntax errors at the end of the file (OpenSCAD reports
// a line past the end, 3Dica the line of the unclosed string, comment or bracket), CRLF line ends (OpenSCAD counts
// each as two lines) and a byte-order mark (OpenSCAD refuses the file).
import { describe, expect, test } from 'vitest'
import { interpret } from '../../src/openscad/interp'
import { ScadError, type InterpretOptions, type ScadMessage, type SourcePos } from '../../src/openscad/types'

const where = (p?: SourcePos) => (p ? ` in file ${p.file ? p.file.split('/').pop() : 'main.scad'}, line ${p.line}` : '')
const line = (m: ScadMessage) => (m.level === 'echo' ? `ECHO: ${m.text}` : `WARNING: ${m.text}${where(m.pos)}`)

/** the console text OpenSCAD would print for `src` */
function consoleText(src: string, opts: InterpretOptions = {}): string {
  try {
    return interpret(src, opts).messages.map(line).join('\n')
  } catch (e) {
    if (!(e instanceof ScadError)) throw e
    const msg = e.message.replace(/^Recursion too deep (calling \w+ '[^']*') \(.*$/, 'Recursion detected $1')
    const error = e.kind === 'syntax' ? `ERROR: Parser error${where(e.pos)}` : `ERROR: ${msg}${where(e.pos)}`
    return [...(e.messages ?? []).map(line), error].join('\n')
  }
}

